class Solution {
    public int maxSizeSlices(int[] slices) {
        int m = slices.length;
        int pick = m / 3;
        if (m == 0) return 0;
        // Case 1: use slices[0..m-2]
        int ans1 = maxForRange(slices, 0, m - 2, pick);
        // Case 2: use slices[1..m-1]
        int ans2 = maxForRange(slices, 1, m - 1, pick);
        return Math.max(ans1, ans2);
    }

    private int maxForRange(int[] slices, int start, int end, int pick) {
        int L = end - start + 1;
        int NEG = -1_000_000_000;
        int[][] dp = new int[L + 1][pick + 1];
        for (int i = 0; i <= L; i++) {
            for (int j = 0; j <= pick; j++) dp[i][j] = NEG;
        }
        dp[0][0] = 0;
        if (L >= 1) dp[1][0] = 0;
        // handle i from 1..L
        for (int i = 1; i <= L; i++) {
            int val = slices[start + i - 1];
            // j = 0 case: pick 0 items => sum 0
            dp[i][0] = 0;
            for (int j = 1; j <= pick; j++) {
                // option 1: not take current
                int notTake = dp[i - 1][j];
                int take = NEG;
                if (i >= 2) {
                    if (dp[i - 2][j - 1] > NEG) take = dp[i - 2][j - 1] + val;
                } else if (i == 1 && j == 1) {
                    take = val;
                }
                dp[i][j] = Math.max(notTake, take);
            }
        }
        return dp[L][pick];
    }
}

